// GetFramebufferViewport queries fixed-size framebuffer/viewport state in one
// cgo transition using C stack storage. split must only be true on a context
// supporting separate read/draw framebuffer bindings. It does not pump events.
func (f *Functions) GetFramebufferViewport(split bool) (draw, read int32, viewport [4]int32) {
	state := C.glowFramebufferViewport(f.gpGetIntegerv, C.int(boolToInt(split)))
	return int32(state.draw), int32(state.read), [4]int32{int32(state.viewport[0]), int32(state.viewport[1]), int32(state.viewport[2]), int32(state.viewport[3])}
}

// GetTargetBindings queries texture, framebuffer and optional pixel-unpack
// buffer bindings in one cgo transition. split/unpack require the corresponding
// context API/extension support; skipped unpack returns zero. The texture is
// the binding on the caller's active texture unit, which this query preserves.
func (f *Functions) GetTargetBindings(split, unpack bool) (texture, draw, read, pixelUnpack int32) {
	state := C.glowTargetBindings(f.gpGetIntegerv, C.int(boolToInt(split)), C.int(boolToInt(unpack)))
	return int32(state.texture), int32(state.draw), int32(state.read), int32(state.unpack)
}

// ShaderSourceString uploads one length-delimited source without a C allocation
// or a Go pointer-to-pointer. It accepts empty sources and requires no final NUL.
// GL copies the source before returning; embedded NULs retain their GL meaning.
func (f *Functions) ShaderSourceString(shader uint32, source string) error {
	if uint64(len(source)) > 0x7fffffff {
		return errors.New("gl: shader source exceeds GLsizei")
	}
	C.glowShaderSourceString(f.gpShaderSource, C.GLuint(shader), (*C.char)(unsafe.Pointer(unsafe.StringData(source))), C.GLint(len(source)))
	return nil
}

// Load resolves a new table from the current context without changing globals.
func Load() (*Functions, error) { return loadFunctions(getProcAddress, true) }

// LoadWithProcAddrFunc resolves plain C names using a caller-supplied resolver.
// On missing required procedures no usable table is returned. Optional
// procedures must be checked together with context version/extension support.
func LoadWithProcAddrFunc(resolve func(string) unsafe.Pointer) (*Functions, error) {
	if resolve == nil {
		return nil, errors.New("gl: nil procedure resolver")
	}
	return loadFunctions(resolve, false)
}
